import { createRequire } from 'node:module'
import fs from 'node:fs'
import path from 'node:path'
import { SLACKR_HOME } from './paths.js'

const require = createRequire(import.meta.url)

function loadSlackr(slackrHome) {
  const slackrLib = require(path.join(slackrHome, 'lib', 'slackr.js'))
  const clientLib = require(path.join(slackrHome, 'lib', 'client.js'))
  return { ...slackrLib, ...clientLib }
}

export function readThreadTs(runDir) {
  const filePath = path.join(runDir, 'slack-run-thread-ts.txt')
  if (!fs.existsSync(filePath)) return null
  return fs.readFileSync(filePath, 'utf8').trim()
}

export async function resolveChannelId({ channel, token, fetchImpl = fetch, slackrHome = SLACKR_HOME } = {}) {
  if (!channel) return null
  if (/^[CG][A-Z0-9]+$/.test(channel)) return channel
  const { requestWithRetry } = loadSlackr(slackrHome)
  const res = await requestWithRetry(fetchImpl, {
    url: 'https://slack.com/api/conversations.list?types=public_channel,private_channel&limit=1000',
    method: 'GET',
    headers: { Authorization: `Bearer ${token}` },
  })
  const json = await res.json()
  if (!json || !json.ok) return null
  const match = (json.channels || []).find((c) => c.name === channel)
  return match ? match.id : null
}

export async function fetchHaltMessage({ channel, token, threadTs, fetchImpl = fetch, slackrHome = SLACKR_HOME }) {
  if (!token || !channel || !threadTs) return { found: false, text: null }
  const { buildRepliesRequest, requestWithRetry } = loadSlackr(slackrHome)
  const req = buildRepliesRequest({ token, channel, ts: threadTs })
  const res = await requestWithRetry(fetchImpl, req)
  const json = await res.json()
  if (!json || !json.ok) return { found: false, text: null }
  const parent = (json.messages || []).find((m) => m.ts === threadTs)
  return parent ? { found: true, text: parent.text } : { found: false, text: null }
}

export async function postHaltReply({ channel, token, threadTs, text, fetchImpl = fetch, slackrHome = SLACKR_HOME }) {
  if (!token || !channel || !text) {
    return { posted: false, channel: null, threadTs: null, notAuthenticated: false, notes: 'missing channel, token, or text' }
  }
  const { postMessage } = loadSlackr(slackrHome)
  return postMessage(fetchImpl, { token, channel, text, threadTs })
}
